import sys, math, json, heapq
sys.path.insert(0,'/app/work')
from solver import *
from collections import defaultdict

class Cluster:
    __slots__=('S','G','n','sumG','lat','reqs')
    def __init__(self,S,G,reqs):
        self.S=S; self.G=G; self.reqs=reqs; self.n=len(reqs)
        self.sumG=sum(r['gen_len'] for r in reqs)
        self.lat=prefill_lat(S)+Dlat(S,G)+8
    def pad(self): return self.n*self.G-self.sumG
    def dcost_total(self):
        return self.n*Dcost(self.S,self.G)+1e7

def build(path):
    R=load(path); g=defaultdict(list)
    for r in R: g[(align(r['prompt_len'],64),r['gen_len'])].append(r)
    return R,[Cluster(S,G,rs) for (S,G),rs in sorted(g.items())]

def optimize(R, clusters, thr, seq_target, pad_budget, exc_budget, cost_budget, verbose=True):
    prefill_total=sum(prefill_cost(align(r['prompt_len'],64)) for r in R)
    cl=list(clusters)
    cost=prefill_total+sum(c.dcost_total() for c in cl)
    seq=sum(c.lat for c in cl)
    pad=sum(c.pad() for c in cl)
    exc=sum(c.n for c in cl if c.lat>thr)
    if verbose:
        print('  start cost %.5e seq %.5e pad %d exc %d clusters %d'%(cost,seq,pad,exc,len(cl)))
    def best_candidate():
        best=None
        for i,h in enumerate(cl):
            hs,hg,hD,hlat=h.S,h.G,Dcost(h.S,h.G),h.lat
            for j,v in enumerate(cl):
                if i==j: continue
                if hs>=v.S and hg>=v.G:
                    dcost=v.n*(hD-Dcost(v.S,v.G))-1e7
                    dpad=v.n*(hg-v.G)
                    dexc=v.n*((1 if hlat>thr else 0)-(1 if v.lat>thr else 0))
                    if pad+dpad<=pad_budget and exc+dexc<=exc_budget:
                        yield dcost,dpad,-v.lat,dexc,i,j
    # Phase A: negative-cost merges (improve both cost and seq)
    while True:
        best=None
        for cand in best_candidate():
            dcost,dpad,dseq,dexc,i,j=cand
            if dcost<=0:
                key=(dseq,dcost)  # most seq saved, then most cost saved
                if best is None or key<best[0]:
                    best=(key,cand)
        if best is None: break
        _,cand=best
        dcost,dpad,dseq,dexc,i,j=cand
        h,v=cl[i],cl[j]
        # merge v into h
        cost+=dcost; seq+=dseq; pad+=dpad; exc+=dexc
        h.reqs=h.reqs+v.reqs; h.n+=v.n; h.sumG+=v.sumG
        cl.pop(j)
        if verbose: pass
    phaseA=(cost,seq,pad,exc,len(cl))
    if verbose: print('  after A: cost %.5e seq %.5e pad %d exc %d clusters %d'%(cost,seq,pad,exc,len(cl)))
    # Phase B: positive-cost merges by best seq-per-cost until seq target
    while seq>seq_target:
        best=None
        for cand in best_candidate():
            dcost,dpad,dseq,dexc,i,j=cand
            if dcost>0:
                ratio=dcost/(-dseq)
                if best is None or ratio<best[0]:
                    best=(ratio,cand)
        if best is None:
            if verbose: print('  no feasible positive merge; seq %.5e target %.5e'%(seq,seq_target))
            break
        _,cand=best
        dcost,dpad,dseq,dexc,i,j=cand
        if cost+dcost>cost_budget:
            if verbose: print('  cost budget would exceed: cost %.5e + %.3e'%(cost,dcost))
            break
        h,v=cl[i],cl[j]
        cost+=dcost; seq+=dseq; pad+=dpad; exc+=dexc
        h.reqs=h.reqs+v.reqs; h.n+=v.n; h.sumG+=v.sumG
        cl.pop(j)
    if verbose: print('  after B: cost %.5e seq %.5e pad %d exc %d clusters %d'%(cost,seq,pad,exc,len(cl)))
    return cl,cost,seq,pad,exc,phaseA
